
.mission-qr {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  text-align: center;
  padding: 0.5rem 0 0.25rem;
}

.mission-qr__icon {
  width: 3rem;
  height: 3rem;
  color: var(--farm-accent-dark);
}

.mission-qr__text {
  margin: 0;
  font-size: 0.92rem;
  color: var(--farm-text-dark);
  font-weight: 600;
}

.mission-qr__hint {
  margin: 0;
  font-size: 0.85rem;
  color: var(--farm-text-muted);
}

.mission-qr__camera {
  width: 100%;
  min-height: 240px;
  border-radius: 0.85rem;
  overflow: hidden;
  background: #000;
}

.mission-qr__status {
  margin: 0;
  font-size: 0.8rem;
  color: var(--farm-text-muted);
}

.mission-qr__status--error {
  color: var(--farm-wood-dark);
  font-weight: 700;
}
